def apply(hou, save=False):
    assert save is False, 'Persistence belongs to cumulative gate'
    node=hou.node('/obj/StreetBuilding_DEV/StreetBuildingCore')
    assert node is not None
    originals={}; merge=node.node('METADATA_ATTACHMENT_INPUTS'); added=merge is None
    meta=node.node('BUILD_METADATA'); old_input=meta.input(3)
    if added:
        assert old_input==node.node('MERGE_DIRECT_BUILDING_INSTANCES'), 'Unexpected metadata dependency'
    else:
        assert old_input==merge, 'Metadata diagnostic input changed'

    try:
        for name,row in PATCHES.items():
            p=node.node(name).parm('snippet');current=p.eval()
            digest=hashlib.sha256(current.encode()).hexdigest()
            assert digest in (row['before'],row['after']), 'Current-Live precondition mismatch: '+name
            originals[p]=current
        if added:
            merge=node.createNode('merge','METADATA_ATTACHMENT_INPUTS')
            merge.setInput(0,node.node('MERGE_DIRECT_BUILDING_INSTANCES'))
            merge.setInput(1,node.node('DETAIL_INSTANCE_POINTS'))
            merge.setInput(2,node.node('SELECT_ATTACHMENT_MODULES'))
            merge.setComment('诊断依赖：墙体实例、附件实际输出及生效规则。显式连线避免并行 Cook 时动态回读旁支。')
            box=next(b for b in node.networkBoxes() if b.name()=='70_UNITY_CONTRACT')
            box.addItem(merge); merge.setPosition(meta.position()+hou.Vector2(-2,1))
            meta.setInput(3,merge)
        for name,row in PATCHES.items():node.node(name).parm('snippet').set(row['code'])
        for name in PATCHES:
            n=node.node(name);n.cook(force=True)
            assert not n.errors() and not n.warnings(), (name,n.errors(),n.warnings())
    except Exception:
        for p,current in originals.items():p.set(current)
        if added:
            meta.setInput(3,old_input)
            if merge is not None:merge.destroy()
        raise
    return {'status':'PASS','save':False,'nodes':list(PATCHES)}
